<script setup lang="ts">
import {readDraft,writeDraft,clearDraft,protectUnload} from '../lib/edit-protection';
import DateTimePicker from '../components/DateTimePicker.vue';import DurationPicker from '../components/DurationPicker.vue';
import {confirmAction,promptAction} from '../lib/dialog';
import { ref,computed,onMounted,watch } from 'vue';import { onBeforeRouteLeave } from 'vue-router';import EventPicker from '../components/EventPicker.vue';import { api,catalog,duration,download,displayTime } from '../lib/api';import { programTypes,type Snapshot,type ProgramItem } from '../../shared/models';
const s=ref<Snapshot|null>(null),items=ref<ProgramItem[]>([]),start=ref(''),error=ref(''),notice=ref(''),busy=ref(false),dirty=ref(false),query=ref(''),pool=ref<{id:string;title:string;type:string;duration_seconds:number;revision_id:string;planned:number}[]>([]),poolPage=ref(1),poolTotal=ref(0),drag=ref(-1);
type Backup={items:ProgramItem[];start:string;version:number};const recovered=ref<Backup|null>(null);let loadedEvent='',hydrating=false,sequence=0,poolSequence=0;const scope=(id=loadedEvent)=>'program:'+id;
const content=()=>JSON.stringify({items:items.value.map(x=>({id:x.id,revision_id:x.revision_id,custom_name:x.custom_name,custom_type:x.custom_type,custom_duration:x.custom_duration,notes:x.notes})),start:start.value});
let saved='';
watch([items,start],()=>{if(hydrating||!loadedEvent)return;dirty.value=content()!==saved;if(dirty.value){if(!writeDraft(scope(),{items:items.value,start:start.value,version:s.value!.program.version}))notice.value='本机备份不可用，请及时保存并保留此页。';}else clearDraft(scope());},{deep:true,flush:'sync'});
async function load(){const id=catalog.eventId,seq=++sequence;if(!id)return;try{const snap=await api<Snapshot>('/api/admin/events/'+id+'/program');if(seq!==sequence)return;hydrating=true;loadedEvent=id;s.value=snap;items.value=structuredClone(snap.items);start.value=snap.program.starts_at??'';saved=content();dirty.value=false;notice.value='';recovered.value=readDraft<Backup>(scope());hydrating=false;if(recovered.value&&recovered.value.version===snap.program.version&&!snap.program.locked&&!snap.document.locked)await restore();await loadPool();}catch(e){error.value=(e as Error).message;}finally{hydrating=false;}}
async function restore(){const b=recovered.value;if(!b||!s.value||!unlocked.value)return;if(b.version!==s.value.program.version&&!await confirmAction('服务器节目单已更新。恢复本机草稿将以本机内容作为新的编辑稿，之后保存会替换当前编排，是否恢复？'))return;error.value='';items.value=JSON.parse(JSON.stringify(b.items));start.value=b.start;recovered.value=null;notice.value='已恢复本机未保存的节目单，请检查后保存。';}
function discard(){clearDraft(scope());recovered.value=null;void load();}
async function loadPool(){const id=catalog.eventId,seq=++poolSequence;const v=await api<{items:typeof pool.value;total:number}>('/api/admin/submissions?event='+id+'&status=approved&q='+encodeURIComponent(query.value)+'&page='+poolPage.value);if(seq!==poolSequence||id!==catalog.eventId)return;pool.value=v.items;poolTotal.value=v.total;}
let reverting=false;watch(()=>catalog.eventId,async(id,old)=>{if(reverting){reverting=false;return;}if(!busy.value&&(!dirty.value||await confirmAction('节目单尚未保存，切换后可恢复本机草稿。是否切换？'))){poolPage.value=1;await load();}else{reverting=true;catalog.eventId=old;}});onMounted(load);watch(query,()=>{poolPage.value=1;void loadPool().catch(e=>error.value=e.message);});
const total=computed(()=>items.value.reduce((n,x)=>n+(x.revision_id?x.duration_seconds??0:x.custom_duration??0),0));
const unlocked=computed(()=>s.value&&!s.value.program.locked&&!s.value.document.locked);
function move(index:number,offset:number){const target=index+offset;if(target<0||target>=items.value.length)return;const [x]=items.value.splice(index,1);items.value.splice(target,0,x!);}
function add(x:typeof pool.value[number]){if(items.value.some(i=>i.revision_id===x.revision_id))return;items.value.push({id:crypto.randomUUID(),position:items.value.length,revision_id:x.revision_id,custom_name:null,custom_type:null,custom_duration:null,notes:'',title:x.title,type:x.type,duration_seconds:x.duration_seconds});}
function custom(){items.value.push({id:crypto.randomUUID(),position:items.value.length,revision_id:null,custom_name:'',custom_type:'翻唱',custom_duration:60,notes:''});}
async function save(){if(!s.value||busy.value)return;const eventId=loadedEvent,version=s.value.program.version,sent=content();busy.value=true;error.value='';try{const payload=JSON.parse(sent);if(items.value.some(x=>!x.revision_id&&/^其他[：:]?$/.test(x.custom_type??'')))throw new Error('请说明临时节目的具体类型');const at=payload.start?new Date(payload.start).toISOString():null;const result=await api<{version:number}>('/api/admin/events/'+eventId+'/program',{operation_id:crypto.randomUUID(),expectedVersion:version,starts_at:at,items:payload.items},'PUT');if(eventId!==loadedEvent)return;s.value.program.version=result.version;s.value.program.starts_at=at;saved=sent;dirty.value=content()!==sent;if(dirty.value){writeDraft(scope(eventId),{items:items.value,start:start.value,version:result.version});notice.value='已保存上一版，后续输入仍待保存。';}else{clearDraft(scope(eventId));notice.value='节目单已保存。';}}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function lock(){if(!s.value||busy.value)return;if(dirty.value){error.value='请先保存节目单';return;}const reason=s.value.program.locked?await promptAction('填写解锁原因（原定稿会失效）'):'';if(reason===null)return;busy.value=true;try{await api('/api/admin/events/'+loadedEvent+'/program/lock',{operation_id:crypto.randomUUID(),expectedVersion:s.value.program.version,locked:!s.value.program.locked,reason});await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function elapsed(index:number){return duration(items.value.slice(0,index).reduce((n,x)=>n+(x.revision_id?x.duration_seconds??0:x.custom_duration??0),0));}
function drop(index:number){if(drag.value<0)return;const [x]=items.value.splice(drag.value,1);items.value.splice(index,0,x!);drag.value=-1;}
const removed=ref<{item:ProgramItem;index:number}|null>(null);function remove(index:number){removed.value={item:items.value[index]!,index};items.value.splice(index,1);}function undo(){if(!removed.value)return;items.value.splice(removed.value.index,0,removed.value.item);removed.value=null;}
protectUnload(()=>dirty.value||busy.value);onBeforeRouteLeave(async()=>!busy.value&&(!dirty.value||await confirmAction('节目单尚未保存，本机草稿会保留。确定离开？')));
</script>
<template><div class="page"><header class="page-head"><div><h1>节目编排</h1></div><EventPicker :disabled="busy"/></header><p v-if="error" class="alert error" role="alert">{{ error }}</p><p v-if="notice" class="hint" role="status">{{ notice }}</p><div v-if="recovered" class="alert warning">检测到本机未保存的编排。<button :disabled="!unlocked" @click="restore">恢复草稿</button><button @click="discard">使用服务器版本</button></div><div v-if="removed" class="alert" role="status">已移除节目。<button @click="undo">撤销移除</button></div><template v-if="s"><div class="toolbar paper"><div><strong>{{ items.length }} 个节目 · {{ duration(total) }}</strong><small>版本 {{ s.program.version }} · {{ s.program.locked?'编排已锁定':'编排中' }}</small></div><div class="inline"><button @click="download('/api/admin/events/'+catalog.eventId+'/program/export','节目单.csv')">导出 CSV</button><button :disabled="busy" @click="lock">{{ s.program.locked?'解锁编排':'锁定编排' }}</button><button class="primary" :disabled="busy||!dirty||!unlocked" @click="save">{{ busy?'保存中…':dirty?'保存修改':'已保存' }}</button></div></div><div class="program-layout"><section class="paper"><DateTimePicker v-model="start" label="开演时间" :timezone="catalog.events.find(e=>e.id===catalog.eventId)?.timezone" :disabled="!unlocked"/><p class="hint">{{ displayTime(s.program.starts_at,catalog.events.find(e=>e.id===catalog.eventId)?.timezone) }} · 时长仅计算节目本身，主持段落另计。</p><div v-for="(item,index) in items" :key="item.id" class="program-row" :draggable="!!unlocked" @dragstart="drag=index" @dragover.prevent @drop.prevent="drop(index)"><span class="program-index">{{ String(index+1).padStart(2,'0') }}<small>{{ elapsed(index) }}</small></span><div class="grow"><template v-if="item.revision_id"><RouterLink :to="'/admin/submissions/'+pool.find(p=>p.revision_id===item.revision_id)?.id" v-if="pool.some(p=>p.revision_id===item.revision_id)">{{ item.title }}</RouterLink><strong v-else>{{ item.title }}</strong><small>{{ item.type }} · {{ duration(item.duration_seconds??0) }}</small></template><div v-else class="grid three"><label>临时节目名称<input v-model="item.custom_name" :disabled="!unlocked"></label><label>类型<select :value="item.custom_type?.startsWith('其他')?'其他':item.custom_type" :disabled="!unlocked" @change="item.custom_type=($event.target as HTMLSelectElement).value"><option v-for="t in programTypes">{{ t }}</option></select></label><DurationPicker :model-value="item.custom_duration??0" :disabled="!unlocked" @update:model-value="item.custom_duration=$event"/></div><label v-if="!item.revision_id&&item.custom_type?.startsWith('其他')">具体节目类型 *<input :value="item.custom_type.replace(/^其他[：:]?/,'')" required maxlength="90" :disabled="!unlocked" @input="item.custom_type='其他：'+($event.target as HTMLInputElement).value"></label><label class="compact-label">编排备注<input v-model="item.notes" :disabled="!unlocked"></label></div><div v-if="unlocked" class="row-actions"><button :disabled="index===0" aria-label="上移节目" @click="move(index,-1)">↑</button><button :disabled="index===items.length-1" aria-label="下移节目" @click="move(index,1)">↓</button><button class="text-button danger" @click="remove(index)">移除</button></div></div><p v-if="!items.length" class="empty">从右侧添加第一个节目。</p><button v-if="unlocked" @click="custom">＋ 添加临时节目</button><p class="hint">移除节目后，已填写的主持段落保留待重新定位；空的自动段落会归档。</p></section><aside class="paper"><h2>已通过投稿</h2><label>搜索节目<input v-model="query" type="search" placeholder="标题 / 负责人 / UID"></label><article v-for="p in pool" :key="p.id" class="pool-card"><RouterLink :to="'/admin/submissions/'+p.id">{{ p.title }}</RouterLink><small>{{ p.type }} · {{ duration(p.duration_seconds) }}</small><button :disabled="!unlocked||items.some(x=>x.revision_id===p.revision_id)" @click="add(p)">{{ items.some(x=>x.revision_id===p.revision_id)?'已添加':'加入节目单' }}</button></article><p v-if="!pool.length" class="empty">尚无可编排的投稿。</p><div class="inline"><button :disabled="poolPage===1" @click="poolPage--;loadPool()">上一页</button><span>{{ poolPage }}</span><button :disabled="poolPage*20>=poolTotal" @click="poolPage++;loadPool()">下一页</button></div></aside></div></template></div></template>
